  2→import { readFileSync, writeFileSync, existsSync } from 'node:fs';
  3→import { join } from 'node:path';
  4→import { createServer } from 'node:http';
  5→import { execSync } from 'node:child_process';
  6→import { cpus, totalmem, freemem, hostname } from 'node:os';
  7→
  8→const HISTORY_FILE = 'workflow-history.json';
  9→const MAX_HISTORY = 100;
 10→
 11→/** @typedef {import('../../miniapp-api.js').MiniAppContext} MiniAppContext */
 12→/** @typedef {import('../../miniapp-api.js').MiniAppLifecycle} MiniAppLifecycle */
 13→
 14→export async function start(context) {
 15→  const clientEntry = readFileSync(join(context.pluginRoot, 'miniapp/client/index.html'), 'utf-8');
 16→  const historyPath = join(context.dataDir, HISTORY_FILE);
 17→
 18→  // --- SSE clients ---
 19→  const clients = new Set();
 20→
 21→  function broadcast(data) {
 22→    const payload = `data: ${JSON.stringify(data)}\n\n`;
 23→    for (const res of clients) {
 24→      try { res.write(payload); } catch (_) { clients.delete(res); }
 25→    }
 26→  }
 27→
 28→  // --- Data fetching helpers ---
 29→  function getSystemInfo() {
 30→    const cpuList = cpus();
 31→    const totalMem = totalmem();
 32→    const freeMem = freemem();
 33→    const usedMem = totalMem - freeMem;
 34→    const memPct = Math.round((usedMem / totalMem) * 100);
 35→
 36→    // CPU usage estimation — average across cores
 37→    let totalIdle = 0, totalTick = 0;
 38→    for (const cpu of cpuList) {
 39→      for (const type in cpu.times) totalTick += cpu.times[type];
 40→      totalIdle += cpu.times.idle;
 41→    }
 42→    const cpuPct = Math.round(100 - (totalIdle / totalTick) * 100);
 43→
 44→    return {
 45→      hostname: hostname(),
 46→      cpuCores: cpuList.length,
 47→      cpuModel: cpuList[0]?.model ?? 'unknown',
 48→      cpuPct,
 49→      memUsed: usedMem,
 50→      memTotal: totalMem,
 51→      memPct,
 52→    };
 53→  }
 54→
 55→  function getProcessList() {
 56→    try {
 57→      // Windows: get top processes by memory
 58→      const out = execSync(
 59→        'powershell -Command "Get-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First 20 Name,Id,@{N=\'CPU\';E={[math]::Round($_.CPU,1)}},@{N=\'MemoryMB\';E={[math]::Round($_.WorkingSet64/1MB,1)}} | ConvertTo-Json"',
 60→        { timeout: 8000, encoding: 'utf-8', maxBuffer: 1024 * 1024 }
 61→      );
 62→      const parsed = JSON.parse(out);
 63→      return Array.isArray(parsed) ? parsed : [parsed];
 64→    } catch (_) {
 65→      return [];
 66→    }
 67→  }
 68→
 69→  function getServices() {
 70→    try {
 71→      const out = execSync(
 72→        'powershell -Command "Get-Service | Where-Object {$_.Status -eq \'Running\'} | Select-Object -First 20 Name,DisplayName,Status | ConvertTo-Json"',
 73→        { timeout: 8000, encoding: 'utf-8', maxBuffer: 1024 * 1024 }
 74→      );
 75→      const parsed = JSON.parse(out);
 76→      return Array.isArray(parsed) ? parsed : [parsed];
 77→    } catch (_) {
 78→      return [];
 79→    }
 80→  }
 81→
 82→  function loadHistory() {
 83→    try {
 84→      if (!existsSync(historyPath)) return [];
 85→      const raw = readFileSync(historyPath, 'utf-8');
 86→      return JSON.parse(raw);
 87→    } catch (_) {
 88→      return [];
 89→    }
 90→  }
 91→
 92→  function saveHistory(arr) {
 93→    try {
 94→      writeFileSync(historyPath, JSON.stringify(arr.slice(-MAX_HISTORY)), 'utf-8');
 95→    } catch (_) {}
 96→  }
 97→
 98→  // --- REST API routes ---
 99→  const server = createServer(async (request, response) => {
100→    const url = new URL(request.url ?? '/', 'http://miniapp.local');
101→
102→    // CORS + SSE
103→    response.setHeader('Access-Control-Allow-Origin', '*');
104→    response.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
105→    response.setHeader('Access-Control-Allow-Headers', 'Content-Type');
106→
107→    if (request.method === 'OPTIONS') { response.writeHead(204); response.end(); return; }
108→
109→    try {
110→      if (request.method === 'GET' && url.pathname === '/dashboard') {
111→        response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
112→        response.end(clientEntry);
113→        return;
114→      }
115→
116→      if (request.method === 'GET' && url.pathname === '/api/system') {
117→        response.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
118→        response.end(JSON.stringify(getSystemInfo()));
119→        return;
120→      }
121→
122→      if (request.method === 'GET' && url.pathname === '/api/processes') {
123→        response.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
124→        response.end(JSON.stringify(getProcessList()));
125→        return;
126→      }
127→
128→      if (request.method === 'GET' && url.pathname === '/api/services') {
129→        response.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
130→        response.end(JSON.stringify(getServices()));
131→        return;
132→      }
133→
134→      if (request.method === 'GET' && url.pathname === '/api/history') {
135→        response.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
136→        response.end(JSON.stringify(loadHistory()));
137→        return;
138→      }
139→
140→      if (request.method === 'POST' && url.pathname === '/api/workflow') {
141→        let body = '';
142→        request.on('data', chunk => body += chunk);
143→        request.on('end', () => {
144→          try {
145→            const { task, status, result } = JSON.parse(body);
146→            if (!task) { response.writeHead(400); response.end('{"error":"task required"}'); return; }
147→            const entry = {
148→              id: Date.now().toString(36),
149→              task,
150→              status: status ?? 'running',
151→              result: result ?? '',
152→              startedAt: new Date().toISOString(),
153→              updatedAt: new Date().toISOString(),
154→            };
155→            const history = loadHistory();
156→            history.push(entry);
157→            saveHistory(history);
158→            broadcast({ type: 'workflow_update', entry });
159→            response.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
160→            response.end(JSON.stringify(entry));
161→          } catch (_) {
162→            response.writeHead(400); response.end('{"error":"invalid body"}');
163→          }
164→        });
165→        return;
166→      }
167→
168→      if (request.method === 'PATCH' && url.pathname.startsWith('/api/workflow/')) {
169→        const id = url.pathname.replace('/api/workflow/', '');
170→        let body = '';
171→        request.on('data', chunk => body += chunk);
172→        request.on('end', () => {
173→          try {
174→            const updates = JSON.parse(body);
175→            const history = loadHistory();
176→            const idx = history.findIndex(e => e.id === id);
177→            if (idx === -1) { response.writeHead(404); response.end('{"error":"not found"}'); return; }
178→            history[idx] = { ...history[idx], ...updates, updatedAt: new Date().toISOString() };
179→            saveHistory(history);
180→            broadcast({ type: 'workflow_update', entry: history[idx] });
181→            response.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
182→            response.end(JSON.stringify(history[idx]));
183→          } catch (_) {
184→            response.writeHead(400); response.end('{"error":"invalid body"}');
185→          }
186→        });
187→        return;
188→      }
189→
190→      if (request.method === 'GET' && url.pathname === '/api/stream') {
191→        response.writeHead(200, {
192→          'Content-Type': 'text/event-stream',
193→          'Cache-Control': 'no-cache',
194→          'Connection': 'keep-alive',
195→        });
196→        clients.add(response);
197→        // Send initial snapshot
198→        response.write(`data: ${JSON.stringify({ type: 'connected' })}\n\n`);
199→        return;
200→      }
201→
202→      response.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
203→      response.end(JSON.stringify({ error: 'not_found' }));
204→    } catch (err) {
205→      context.logger.error('pipeline-monitor.request_error', { message: String(err) });
206→      response.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
207→      response.end(JSON.stringify({ error: 'internal_error' }));
208→    }
209→  });
210→
211→  // Periodically broadcast system stats
212→  const interval = setInterval(() => {
213→    try {
214→      broadcast({ type: 'system', data: getSystemInfo() });
215→    } catch (_) {}
216→  }, 5000);
217→
218→  await listen(server, context.listen.host, context.listen.port);
219→  context.logger.info('pipeline-monitor.listening');
220→
221→  let disposed = false;
222→  const dispose = async () => {
223→    if (disposed) return;
224→    disposed = true;
225→    clearInterval(interval);
226→    for (const res of clients) { try { res.end(); } catch (_) {} }
227→    context.signal.removeEventListener('abort', onAbort);
228→    await close(server);
229→  };
230→  const onAbort = () => { void dispose(); };
231→  context.signal.addEventListener('abort', onAbort, { once: true });
232→  if (context.signal.aborted) await dispose();
233→
234→  return { dispose };
235→}
236→
237→function listen(server, host, port) {
238→  return new Promise((resolve, reject) => {
239→    const onError = (err) => reject(err);
240→    server.once('error', onError);
241→    server.listen(port, host, () => {
242→      server.off('error', onError);
243→      resolve();
244→    });
245→  });
246→}
247→
248→function close(server) {
249→  return new Promise((resolve, reject) => {
250→    server.close(err => err ? reject(err) : resolve());
251→  });
252→}

